import React, { useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDropzone } from 'react-dropzone';
import { uploadDocuments, analyzeCompany } from '../api/api';
import SimpleButton from '../components/SimpleButton';

const SimpleUploadPage = () => {
  const navigate = useNavigate();
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');

  const onDrop = useCallback(acceptedFiles => {
    const newFiles = acceptedFiles.map(file => ({
      file,
      id: Math.random().toString(36).substr(2, 9),
      preview: URL.createObjectURL(file)
    }));
    console.log('Dropped files:', newFiles.map(f => ({ 
      name: f.file.name, 
      size: f.file.size, 
      type: f.file.type,
      isFile: f.file instanceof File
    })));
    setFiles(prev => [...prev, ...newFiles]);
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'application/pdf': ['.pdf'],
      'application/vnd.ms-excel': ['.xls'],
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
      'text/csv': ['.csv'],
      'image/*': ['.jpg', '.jpeg', '.png', '.tiff']
    }
  });

  const handleUpload = async () => {
    if (files.length === 0) {
      setError('Please upload at least one document');
      return;
    }

    setUploading(true);
    setError('');

    try {
      // Extract files from the file objects
      const fileArray = files.map(item => item.file);
      console.log('Files to upload:', fileArray.map(f => ({ 
        name: f.name, 
        size: f.size, 
        type: f.type,
        isFile: f instanceof File,
        lastModified: f.lastModified,
        constructor: f.constructor.name
      })));

      // Validate files before sending
      if (fileArray.length === 0 || !fileArray[0]) {
        throw new Error('No valid files found');
      }

      const response = await uploadDocuments(fileArray);
      console.log('Upload response:', response);

      if (response.status === 'success') {
        // Store the entire response for debugging
        console.log('Full upload response:', JSON.stringify(response, null, 2));

        // Store the company data from the response
        if (response.documents && response.documents.length > 0) {
          const companyData = response.documents[0];
          console.log('Company data to store:', companyData);
          localStorage.setItem('companyData', JSON.stringify(companyData));

          // Verify it was stored
          const storedData = localStorage.getItem('companyData');
          console.log('Data stored in localStorage:', storedData);

          console.log('Navigating to dashboard...');
          navigate('/dashboard');
        } else {
          console.error('No company data in response:', response);
          setError('No company data received from upload');
        }
      } else {
        console.error('Upload failed - status:', response.status);
        setError('Upload failed: ' + (response.message || 'Unknown error'));
      }
    } catch (err) {
      console.error('Upload error details:', err);
      console.error('Error type:', typeof err);
      console.error('Error message:', err.message);
      console.error('Error stack:', err.stack);
      setError('Upload failed: ' + (err.message || 'Unknown error'));
    } finally {
      setUploading(false);
    }
  };

  const removeFile = (id) => {
    setFiles(prev => prev.filter(file => file.id !== id));
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="min-h-screen bg-gray-50 py-12 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-12">
          <h1 className="text-4xl font-bold text-gray-900 mb-4">
            AI Credit Decisioning Engine
          </h1>
          <p className="text-lg text-gray-600">
            Upload your financial documents for intelligent credit analysis
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Upload Area */}
          <div className="bg-white rounded-lg shadow-md p-8">
            <h2 className="text-xl font-semibold text-gray-900 mb-6">Upload Documents</h2>

            <div
              {...getRootProps()}
              className={`border-2 border-dashed rounded-lg p-12 text-center cursor-pointer ${
                isDragActive ? 'border-blue-500 bg-blue-50' : 'border-gray-300 hover:border-blue-400'
              }`}
            >
              <input {...getInputProps()} />
              <div className="flex flex-col items-center">
                <svg className={`w-16 h-16 mb-4 ${isDragActive ? 'text-blue-600' : 'text-gray-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                </svg>
                <p className="text-lg font-medium text-gray-900 mb-2">
                  {isDragActive ? 'Drop files here' : 'Drag & drop files here'}
                </p>
                <p className="text-sm text-gray-500">or click to browse</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
          <div className="text-center mb-8">
            <div className="text-6xl mb-4">📁</div>
            <h2 className="text-2xl font-bold text-gray-900 mb-2">Upload Financial Documents</h2>
            <p className="text-gray-600">
              Upload PDF files containing financial statements, balance sheets, or income statements
            </p>
          </div>

          {/* Upload Area with enhanced styling */}
          <div
            className={`border-2 border-dashed rounded-xl p-8 text-center transition-all duration-200 ${
              isDragActive
                ? 'border-blue-500 bg-blue-50 scale-105'
                : 'border-gray-300 hover:border-gray-400 bg-gray-50'
            }`}
            {...getRootProps()}
          >
            <div className="text-6xl mb-4">📄</div>
            <p className="text-lg font-medium text-gray-700 mb-2">
              Drag and drop your files here
            </p>
            <p className="text-sm text-gray-500 mb-4">or</p>
            <input
              {...getInputProps()}
              type="file"
              multiple
              accept=".pdf,.doc,.docx"
              className="hidden"
              id="file-upload"
            />
            <label
              htmlFor="file-upload"
              className="inline-block bg-blue-600 text-white px-6 py-3 rounded-lg cursor-pointer hover:bg-blue-700 transition-colors duration-200 font-semibold"
            >
              Browse Files
            </label>
            <p className="text-xs text-gray-500 mt-4">
              Supported formats: PDF, DOC, DOCX (Max 10MB per file)
            </p>
          </div>

          {/* File List with enhanced styling */}
          {files.length > 0 && (
            <div className="mt-8">
              <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
                <span className="mr-2">📋</span>
                Selected Files ({files.length})
              </h3>
              <div className="space-y-3">
                {files.map((file) => (
                  <div
                    key={file.id}
                    className="flex items-center justify-between p-4 bg-gray-50 rounded-xl border border-gray-200 hover:bg-gray-100 transition-colors duration-200"
                  >
                    <div className="flex items-center space-x-3">
                      <div className="text-2xl">📄</div>
                      <div>
                        <p className="font-medium text-gray-900">{file.file.name}</p>
                        <p className="text-sm text-gray-500">{formatFileSize(file.file.size)}</p>
                      </div>
                    </div>
                    <button
                      onClick={() => removeFile(file.id)}
                      className="text-red-500 hover:text-red-700 p-2 rounded-lg hover:bg-red-50 transition-colors duration-200"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Upload Button with enhanced styling */}
          <div className="mt-8 text-center">
            <SimpleButton
              onClick={handleUpload}
              disabled={files.length === 0 || uploading}
              className={`px-8 py-4 rounded-xl font-bold text-lg shadow-lg transform transition-all duration-200 ${
                files.length === 0 || uploading
                  ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                  : 'bg-gradient-to-r from-green-600 to-emerald-600 text-white hover:from-green-700 hover:to-emerald-700 hover:scale-105'
              }`}
            >
              {uploading ? (
                <div className="flex items-center space-x-2">
                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                  <span>Processing with AI...</span>
                </div>
              ) : (
                <div className="flex items-center space-x-2">
                  <span>🚀</span>
                  <span>Start AI Analysis</span>
                </div>
              )}
            </SimpleButton>
            <p className="text-sm text-gray-500 mt-4">
              AI will analyze your documents and generate comprehensive credit insights
            </p>
          </div>

          {/* Error Message with enhanced styling */}
          {error && (
            <div className="mt-6 p-4 bg-red-50 border border-red-200 rounded-xl">
              <div className="flex items-center space-x-3">
                <div className="text-2xl">⚠️</div>
                <div>
                  <p className="text-red-800 font-medium">Upload Error</p>
                  <p className="text-red-600 text-sm">{error}</p>
                </div>
              </div>
            </div>
          )}

          {/* Success Message with enhanced styling */}
          {uploadSuccess && (
            <div className="mt-6 p-4 bg-green-50 border border-green-200 rounded-xl">
              <div className="flex items-center space-x-3">
                <div className="text-2xl">✅</div>
                <div>
                  <p className="text-green-800 font-medium">Upload Successful!</p>
                  <p className="text-green-600 text-sm">Redirecting to your analysis dashboard...</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SimpleUploadPage;
